begin;
select no_plan();
select is((select count(*)::int from pg_policies where schemaname='public' and tablename='status_votes'),4,'exactly four vote policies, no permissive ALL bypass');
select ok(not exists(select 1 from pg_policies where schemaname='public' and tablename='status_votes' and (cmd='ALL' or roles<>array['authenticated']::name[])), 'policies limited to authenticated and one operation');
select ok(not has_table_privilege('anon','public.status_votes','SELECT,INSERT,UPDATE,DELETE'), 'anon has no vote table privileges');
select ok(not has_column_privilege('authenticated','public.status_votes','created_at','INSERT'), 'cannot forge creation timestamp');
select ok(not has_column_privilege('authenticated','public.status_votes','created_at','UPDATE'), 'cannot update creation timestamp');
select ok(not has_table_privilege('authenticated','public.status_votes','TRUNCATE,TRIGGER,REFERENCES'), 'no administrative vote privileges');
select ok(not has_function_privilege('anon','public.get_poll_results(uuid)','EXECUTE'), 'anon cannot call single aggregate');
select ok(not has_function_privilege('anon','public.get_poll_results_batch(uuid[])','EXECUTE'), 'anon cannot call batch aggregate');
select ok(not has_function_privilege('authenticated','private.validate_poll_vote()','EXECUTE'), 'client cannot directly execute trigger');
select is((select relrowsecurity from pg_class where oid='public.status_votes'::regclass),true,'vote RLS remains enabled');
select ok((select proconfig @> array['search_path=""'] from pg_proc where oid='public.get_poll_results(uuid)'::regprocedure), 'single aggregate has empty search_path');
select ok(private.poll_has_option('[{"id":"a","label":"A"},{"id":"b","label":"B"}]','a'), 'valid exact string option');
select ok(not private.poll_has_option('[{"id":"a","label":"A"}]','A'), 'case sensitive option');
select ok(not private.poll_has_option('[{"id":"a","label":"A"}]',' a'), 'no trimming arbitrary option');
select ok(not private.poll_has_option('[{"id":12,"label":"A"}]','12'), 'numeric JSON option is not a string');
select ok(not private.poll_has_option('[null,{"id":"a"}]','a'), 'invalid label rejected');
select ok(not private.poll_has_option(null,'a'), 'null options rejected');
select ok(not private.poll_has_option('{}','a'), 'nonarray options safely rejected');
select ok(not private.poll_has_option('[]',null), 'null option rejected');
select is((select count(*)::int from pg_constraint where conrelid='public.status_votes'::regclass and contype='p'),1, 'original unique primary key preserved');
select * from finish();
rollback;
